import {isLoggedIn} from '@github-ui/client-env'

import {
  GROUP_LABELS,
  GROUP_ORDER,
  type QuickSearchSuggestion,
  type RenderedGroup,
  type SuggestionGroup,
} from '../quick-search-types'

function getGroupLabels(): Record<SuggestionGroup, string> {
  if (isLoggedIn()) return GROUP_LABELS

  return {
    ...GROUP_LABELS,
    suggestions: 'Explore',
  }
}

export function buildRenderedGroups(suggestions: QuickSearchSuggestion[]): RenderedGroup[] {
  const buckets = new Map<SuggestionGroup, QuickSearchSuggestion[]>()
  for (const s of suggestions ?? []) {
    const bucket = buckets.get(s.group) ?? []
    bucket.push(s)
    buckets.set(s.group, bucket)
  }

  const groups: RenderedGroup[] = []
  let flatIndex = 0
  const groupLabels = getGroupLabels()
  for (const groupKey of GROUP_ORDER) {
    const items = buckets.get(groupKey)
    const hasItems = !!items && items.length > 0
    if (hasItems) {
      groups.push({
        label: groupLabels[groupKey],
        items: (items ?? []).map(suggestion => ({suggestion, flatIndex: flatIndex++})),
      })
    }
  }
  return groups
}
