import {type ARIAFilterSuggestion, FilterValueType} from '@github-ui/filter-core/types'

import type {QuickSearchSuggestion} from '../quick-search-types'

// ─── Query parsing helpers ────────────────────────────────────────────────────

const isOrgToken = (token: string): boolean => /^org:/i.test(token)
const isRepoToken = (token: string): boolean => /^repo:/i.test(token)

/**
 * Returns the space-separated segment that contains the caret and its
 * start/end offsets within the full query string.
 *
 * When the caret sits on a space boundary (e.g. right after `org:github `)
 * the active segment is empty — meaning the user has finished that token
 * and we should show initial / default suggestions.
 */
function getActiveSegment(query: string, caretPosition: number) {
  if (!query) return {text: '', start: 0, end: 0}

  // Walk backwards from caret to find the start of the segment
  let start = caretPosition
  while (start > 0 && query[start - 1] !== ' ') start--

  // Walk forwards from caret to find the end of the segment
  let end = caretPosition
  while (end < query.length && query[end] !== ' ') end++

  const text = query.slice(start, end)

  // If the caret is right on a space boundary (nothing between start..end that
  // the caret is in the middle of), treat as empty segment.
  if (
    start === end ||
    (caretPosition > 0 &&
      query[caretPosition - 1] === ' ' &&
      (caretPosition >= query.length || query[caretPosition] === ' '))
  ) {
    return {text: '', start: caretPosition, end: caretPosition}
  }

  return {text, start, end}
}

/**
 * Inspects *all* space-separated tokens in the query (excluding the active
 * segment) to detect already-applied org:/repo: scopes.
 *
 * This ensures that `repo:foo org:github` and `org:github repo:foo` both
 * detect the org filter regardless of where the caret is positioned.
 */
function extractFilters(query: string, activeSegmentStart: number, activeSegmentEnd: number) {
  const tokens = query.split(' ')
  let offset = 0
  let hasOrgFilter = false
  let hasRepoFilter = false
  const nonFilterParts: string[] = []

  for (const token of tokens) {
    const tokenStart = offset
    const tokenEnd = offset + token.length
    offset = tokenEnd + 1 // +1 for the space

    const isActiveSegment = tokenStart < activeSegmentEnd && tokenEnd > activeSegmentStart

    if (isOrgToken(token)) {
      // The active segment isn't a "completed" filter — the user is still typing it
      if (!isActiveSegment) hasOrgFilter = true
    } else if (isRepoToken(token)) {
      if (!isActiveSegment) hasRepoFilter = true
    } else if (token) {
      nonFilterParts.push(token)
    }
  }

  return {
    hasOrgFilter,
    hasRepoFilter,
    valueWithoutFilters: nonFilterParts.join(' '),
  }
}

export function parseQuery(value: string, caretPosition?: number) {
  const caret = caretPosition ?? value.length
  const {text: activeSegmentText, start: activeStart, end: activeEnd} = getActiveSegment(value, caret)

  const activeSegmentType = isOrgToken(activeSegmentText) ? 'org' : isRepoToken(activeSegmentText) ? 'repo' : 'plain'

  const activeSegmentValue =
    activeSegmentType === 'org'
      ? activeSegmentText.slice('org:'.length)
      : activeSegmentType === 'repo'
        ? activeSegmentText.slice('repo:'.length)
        : activeSegmentText

  return {
    value,
    caretPosition: caret,
    /** The segment the caret is currently inside, or null when the caret is between tokens. */
    activeSegment: activeSegmentText
      ? {
          type: activeSegmentType,
          /** Active segment text with any qualifier removed */
          value: activeSegmentValue,
          start: activeStart,
          end: activeEnd,
        }
      : null,
    ...extractFilters(value, activeStart, activeEnd),
  }
}

export type ParsedQuery = ReturnType<typeof parseQuery>

// ─── Filter suggestion predicates ────────────────────────────────────────────

/** Strips no/has/exclusive type suggestions — only plain value completions are needed. */
export function isValueSuggestion(s: ARIAFilterSuggestion): boolean {
  return s.type === FilterValueType.Value
}

// ─── Action label ──────────────────────────────────────────────────────────────

export function getActionLabel(suggestion: QuickSearchSuggestion): string | null {
  if (suggestion?.customActionLabel) return suggestion.customActionLabel
  if (suggestion.id === 'copilot-chat') return 'Start a new Copilot thread'
  if (suggestion.action === 'jump-to') return 'Jump to'
  if (suggestion.action === 'autocomplete') return 'Autocomplete'
  return null
}

// ─── Filter-value highlighting ───────────────────────────────────────────────

export type TextSegment =
  | {type: 'plain'; text: string}
  | {type: 'filter-key'; text: string}
  | {type: 'filter-value'; text: string}

/**
 * Splits a string into segments, identifying filter key:value pairs
 * (repo:, org:, owner:, enterprise:) so they can be rendered with
 * accent highlighting.
 */
export function tokenizeFilterText(text: string): TextSegment[] {
  if (!text) return []

  const segments: TextSegment[] = []
  // Match filter tokens like `repo:value`, `org:value`, etc.
  const regex = /\b((?:repo|org|owner|enterprise):)(\S+)/gi
  let lastIndex = 0
  let match: RegExpExecArray | null

  while ((match = regex.exec(text)) !== null) {
    // Plain text before this match
    if (match.index > lastIndex) {
      segments.push({type: 'plain', text: text.slice(lastIndex, match.index)})
    }
    // The key part (e.g. "repo:")
    segments.push({type: 'filter-key', text: match[1]!})
    // The value part (e.g. "github/github-ui")
    segments.push({type: 'filter-value', text: match[2]!})
    lastIndex = match.index + match[0].length
  }

  // Remaining text after last match
  if (lastIndex < text.length) {
    segments.push({type: 'plain', text: text.slice(lastIndex)})
  }

  return segments
}
