import {ClockIcon, CopilotIcon} from '@primer/octicons-react'

import {MAX_RECENT_SEARCHES, RECENT_SEARCHES_KEY} from '../consts/config'
import type {QuickSearchSuggestion} from '../quick-search-types'

function loadRecentSearches(): string[] {
  try {
    const stored = localStorage.getItem(RECENT_SEARCHES_KEY)
    return stored ? (JSON.parse(stored) as string[]) : []
  } catch {
    return []
  }
}

export function saveRecentSearch(query: string): void {
  try {
    const deduped = loadRecentSearches().filter(q => q !== query)
    localStorage.setItem(RECENT_SEARCHES_KEY, JSON.stringify([query, ...deduped].slice(0, MAX_RECENT_SEARCHES)))
  } catch {
    // localStorage not available — ignore
  }
}

export function getRecentSearchSuggestions() {
  return loadRecentSearches().map(
    (q): QuickSearchSuggestion => ({
      id: `recent-${q}`,
      icon: ClockIcon,
      displayName: q,
      href: `/search?q=${encodeURIComponent(q)}`,
      ariaLabel: `Recent search: ${q}`,
      action: 'search' as const,
      group: 'recent' as const,
    }),
  )
}

export const copilotChatSuggestion: QuickSearchSuggestion = {
  id: 'copilot-chat',
  icon: CopilotIcon,
  displayName: 'Chat with Copilot',
  href: '/copilot',
  ariaLabel: 'Open Copilot chat',
  action: 'jump-to' as const,
  group: 'suggestions' as const,
}
