import {queryOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {BookmarkIcon} from '@primer/octicons-react'

import type {QuickSearchSuggestion} from '../../quick-search-types'
import type {ParsedQuery} from '../suggestion-utils'

type SavedSearchSuggestion = {
  name: string
  query: string
}

const SAVED_SEARCH_SUGGESTIONS_PATH = '/search/custom_scopes'

function mapSavedSearchSuggestion(s: SavedSearchSuggestion): QuickSearchSuggestion {
  return {
    id: `saved-search-${s.name}`,
    displayName: s.name,
    icon: BookmarkIcon,
    href: s.query ? `/search?q=${encodeURIComponent(s.query)}` : '/search',
    ariaLabel: `${s.name}, ${s.query}, search this query`,
    action: 'search',
    group: 'saved',
  }
}

export function savedSearchSuggestionsQueryOptions(query: ParsedQuery) {
  return queryOptions({
    queryKey: [SAVED_SEARCH_SUGGESTIONS_PATH],
    queryFn: async () => {
      const response = await reactFetchJSON(SAVED_SEARCH_SUGGESTIONS_PATH)
      if (!response.ok) throw new Error('Failed to fetch saved search suggestions')

      const responseJson = (await response.json()) as SavedSearchSuggestion[]
      return responseJson
    },
    select: (responseJson): QuickSearchSuggestion[] =>
      responseJson
        .filter(s => {
          return s.name?.includes(query.value || '')
        })
        .map(mapSavedSearchSuggestion),
    staleTime: 60 * 1000,
    placeholderData: prev => prev,
  })
}
