import {SymbolKind} from '@github-ui/code-nav'
import {queryOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {FileCodeIcon} from '@primer/octicons-react'

import type {QuickSearchSuggestion} from '../../quick-search-types'
import type {ParsedQuery} from '../suggestion-utils'

type SuggestionKind = 'SUGGESTION_KIND_PATH' | 'SUGGESTION_KIND_SYMBOL'

interface SearchSymbol {
  fully_qualified_name: string
  kind: string
}

interface BaseSearchSuggestion {
  kind: SuggestionKind
  repository_nwo: string
  path: string
  commit_sha: string
  line_number?: number
  symbol: SearchSymbol | null
}

interface SymbolSuggestion extends BaseSearchSuggestion {
  kind: 'SUGGESTION_KIND_SYMBOL'
  symbol: SearchSymbol
}

interface PathSuggestion extends BaseSearchSuggestion {
  kind: 'SUGGESTION_KIND_PATH'
  symbol: null
}

export type CodeSearchSuggestion = SymbolSuggestion | PathSuggestion

export interface CodeSearchSuggestionsResponse {
  failed: boolean
  // queryErrors: unknown[]
  suggestions: CodeSearchSuggestion[]
}

const CODE_SEARCH_SUGGESTIONS_PATH = '/search/suggestions'

function mapCodeSearchSuggestion(s: CodeSearchSuggestion): QuickSearchSuggestion {
  const href = `/${s.repository_nwo}/blob/${s.commit_sha}/${s.path}#L${s.line_number ?? 1}`

  if (s.kind === 'SUGGESTION_KIND_SYMBOL') {
    const description = `${s.repository_nwo} \u2022 ${s.path}`
    const name = s.symbol.fully_qualified_name

    const kind = new SymbolKind(s.symbol)

    return {
      id: `code-symbol-${s.repository_nwo}-${s.path}-${s.symbol.fully_qualified_name}`,
      displayName: name,
      description,
      icon: FileCodeIcon,
      href,
      ariaLabel: `${name}, ${description}, jump to this code`,
      action: 'jump-to',
      group: 'code',
      symbolKind: kind,
    }
  }

  const pathParts = s.path.split('/')
  const name = pathParts.pop() ?? ''
  const description = `${s.repository_nwo}${pathParts.length > 0 ? ` \u2022 ${pathParts.join('/')}` : ''}`

  return {
    id: `code-path-${s.repository_nwo}-${s.path}`,
    displayName: name,
    description,
    icon: FileCodeIcon,
    href,
    ariaLabel: `${name}, ${description}, jump to this code`,
    action: 'jump-to',
    group: 'code',
  }
}

export function codeSearchSuggestionsQueryOptions(query: ParsedQuery) {
  const codeSearchQuery =
    (query.hasOrgFilter || query.hasRepoFilter) && query.activeSegment?.type === 'plain' ? query.value : undefined

  return queryOptions({
    queryKey: [CODE_SEARCH_SUGGESTIONS_PATH, codeSearchQuery],
    queryFn: async () => {
      if (codeSearchQuery === undefined) return []

      const params = new URLSearchParams({query: codeSearchQuery})

      const response = await reactFetchJSON(`${CODE_SEARCH_SUGGESTIONS_PATH}?${params.toString()}`)
      if (!response.ok) throw new Error('Failed to fetch code search suggestions')

      const responseJson = (await response.json()) as CodeSearchSuggestionsResponse
      if (responseJson.failed) throw new Error('Failed to fetch code search suggestions')

      return responseJson.suggestions
    },
    select: (suggestions): QuickSearchSuggestion[] => suggestions.map(mapCodeSearchSuggestion),
    staleTime: 60 * 1000,
    placeholderData: prev => prev,
  })
}
