import {SearchIcon} from '@primer/octicons-react'

import type {QuickSearchSuggestion} from '../quick-search-types'
import type {ParsedQuery} from './suggestion-utils'

export function getContextualSuggestions(
  query: ParsedQuery,
  searchContext?: Record<string, string>,
): QuickSearchSuggestion[] {
  const contextRegex = /(?:^|\s)(repo:[^\s]+|org:[^\s]+|enterprise:[^\s]+)(?=\s|$)/i
  const displayQueryTextWithoutContext = query.value.replace(contextRegex, '').trim()
  const trimmedValue = query.value.trim()

  // lets make a suggestion case for the 4 types of suggestions
  const searchContextSuggestions: QuickSearchSuggestion[] = []
  // Basic search (no context)
  if (!query.hasOrgFilter && !query.hasRepoFilter && displayQueryTextWithoutContext) {
    searchContextSuggestions.push({
      id: `search-${trimmedValue}`,
      icon: SearchIcon,
      displayName: displayQueryTextWithoutContext,
      searchQuery: displayQueryTextWithoutContext,
      href: `/search?q=${encodeURIComponent(displayQueryTextWithoutContext)}`,
      ariaLabel: `Search GitHub for ${displayQueryTextWithoutContext}`,
      action: 'search',
      group: 'contextual',
      insertValue: displayQueryTextWithoutContext,
      customActionLabel: 'Search all of GitHub',
    })
  }

  // Repository-scoped search (repo context)
  if (searchContext?.current_repo_nwo) {
    searchContextSuggestions.push({
      id: `current-repo-nwo-search-${trimmedValue}`,
      icon: SearchIcon,
      displayName: `repo:${searchContext.current_repo_nwo} ${displayQueryTextWithoutContext}`,
      searchQuery: trimmedValue,
      href: `/search?q=${encodeURIComponent(`repo:${searchContext.current_repo_nwo} ${displayQueryTextWithoutContext}`)}`,
      ariaLabel: `Search ${searchContext.current_repo_nwo} for ${displayQueryTextWithoutContext}`,
      action: 'search',
      group: 'contextual',
      customActionLabel: 'Search in this repository',
    })
  }

  // Organization-scoped search (org context)
  if (searchContext?.current_repo_org) {
    searchContextSuggestions.push({
      id: `current-org-search-${trimmedValue}`,
      icon: SearchIcon,
      displayName: `org:${searchContext.current_repo_org} ${displayQueryTextWithoutContext}`,
      searchQuery: trimmedValue,
      href: `/search?q=${encodeURIComponent(`org:${searchContext.current_repo_org} ${displayQueryTextWithoutContext}`)}`,
      ariaLabel: `Search Organization ${searchContext.current_repo_org} for ${displayQueryTextWithoutContext}`,
      action: 'search',
      group: 'contextual',
      customActionLabel: 'Search in this organization',
    })
  }

  // Enterprise scoped search (ent context)
  if (searchContext?.current_business) {
    searchContextSuggestions.push({
      id: `current-enterprise-search-${trimmedValue}`,
      icon: SearchIcon,
      displayName: `enterprise:${searchContext.current_business} ${displayQueryTextWithoutContext}`,
      searchQuery: trimmedValue,
      href: `/search?q=${encodeURIComponent(`enterprise:${searchContext.current_business} ${displayQueryTextWithoutContext}`)}`,
      ariaLabel: `Search Enterprise ${searchContext.current_business} for ${displayQueryTextWithoutContext}`,
      action: 'search',
      group: 'contextual',
      customActionLabel: 'Search in this enterprise',
    })
  }

  // User scoped search (user context)
  if (searchContext?.user_id && !searchContext?.current_repo_org) {
    searchContextSuggestions.push({
      id: `current-user-search-${trimmedValue}`, // consider naming this user-id-search for consistency
      icon: SearchIcon,
      displayName: `owner:${searchContext.user_id} ${displayQueryTextWithoutContext}`,
      searchQuery: trimmedValue,
      href: `/search?q=${encodeURIComponent(`owner:${searchContext.user_id} ${displayQueryTextWithoutContext}`)}`,
      ariaLabel: `Search Owner ${searchContext.user_id} for ${displayQueryTextWithoutContext}`,
      action: 'search',
      group: 'contextual',
      customActionLabel: 'Search in this organization', // this is a bit awkward but it matches dotcom
    })
  }
  return searchContextSuggestions
}
