import {defaultFilterConfig} from '@github-ui/filter-core/constants/defaults'
import {FilterQueryParser} from '@github-ui/filter-core/parser'
import {OrgFilterProvider} from '@github-ui/filter-core/providers/org'
import {RepositoryFilterProvider} from '@github-ui/filter-core/providers/repository'
import {getQueryClient} from '@github-ui/react-core/query-client'

import {FILTER_PROVIDER_OPTIONS} from '../consts/config'
import {orgSuggestionsQueryOptions} from './queries/org-suggestions-query'
import {repoSuggestionsQueryOptions} from './queries/repo-suggestions-query'
import {parseQuery} from './suggestion-utils'

// ─── Module-level providers for pre-warm only ────────────────────────────────
// These are used solely by preloadQuickSearch(). The component creates its own
// providers via useMemo so each instance has isolated caches (important for
// test isolation and correctness).
const prewarmOrgProvider = new OrgFilterProvider(FILTER_PROVIDER_OPTIONS)
const prewarmRepoProvider = new RepositoryFilterProvider(FILTER_PROVIDER_OPTIONS)
const prewarmParser = new FilterQueryParser([prewarmOrgProvider, prewarmRepoProvider], defaultFilterConfig)

/**
 * Triggers a background fetch of the default suggestion set (top orgs/repos,
 * recent searches) and populates `suggestionsCache` for the empty-query key.
 *
 * Safe to call multiple times — if the cache already has an entry for `''`
 * (populated by a previous call or by the component itself) this is a no-op.
 * Intended to be called from hover-intent or other eagerness signals so results
 * are ready before the user opens the dialog.
 */
export function preloadQuickSearch(): void {
  const queryClient = getQueryClient()
  void queryClient.prefetchQuery(repoSuggestionsQueryOptions(parseQuery(''), prewarmRepoProvider, prewarmParser))
  void queryClient.prefetchQuery(orgSuggestionsQueryOptions(parseQuery(''), prewarmOrgProvider, prewarmParser))
}
