import {ActionList} from '@primer/react'
import {SkeletonAvatar, SkeletonText} from '@primer/react/experimental'

import {SKELETON_WIDTHS} from './consts/config'

/**
 * Placeholder animation shown while the initial suggestion fetch is pending
 * (e.g. when the dialog is opened via keyboard shortcut before the pre-warm
 * fetch has resolved).
 */
export function SuggestionSkeletons() {
  return SKELETON_WIDTHS.map((width, i) => (
    // eslint-disable-next-line @eslint-react/no-array-index-key
    <ActionList.Item key={i} aria-label="Loading...">
      <ActionList.LeadingVisual>
        <SkeletonAvatar size={16} />
      </ActionList.LeadingVisual>
      <SkeletonText style={{width}} />
    </ActionList.Item>
  ))
}
