import {
  BeakerIcon,
  BookIcon,
  CodeReviewIcon,
  CodespacesIcon,
  CodeSquareIcon,
  CommentDiscussionIcon,
  CommentIcon,
  CopilotIcon,
  CreditCardIcon,
  DeviceDesktopIcon,
  DeviceMobileIcon,
  GiftIcon,
  GitPullRequestIcon,
  GlobeIcon,
  GraphIcon,
  HeartIcon,
  type Icon,
  IssueOpenedIcon,
  MarkGithubIcon,
  OrganizationIcon,
  PackageIcon,
  PlayIcon,
  RocketIcon,
  SearchIcon,
  ServerIcon,
  ShieldCheckIcon,
  WorkflowIcon,
} from '@primer/octicons-react'

import {MAX_LOGGED_OUT_SUGGESTIONS} from '../consts/config'
import {type ExplorePage, ExplorePages} from '../consts/explore'
import type {QuickSearchSuggestion} from '../quick-search-types'

const EXPLORE_ICON_MAP: Record<string, Icon> = {
  organization: OrganizationIcon,
  'shield-check': ShieldCheckIcon,
  copilot: CopilotIcon,
  'credit-card': CreditCardIcon,
  workflow: WorkflowIcon,
  book: BookIcon,
  'code-review': CodeReviewIcon,
  codespaces: CodespacesIcon,
  comment: CommentIcon,
  'comment-discussion': CommentDiscussionIcon,
  rocket: RocketIcon,
  heart: HeartIcon,
  server: ServerIcon,
  globe: GlobeIcon,
  'issue-opened': IssueOpenedIcon,
  'device-mobile': DeviceMobileIcon,
  package: PackageIcon,
  play: PlayIcon,
  gift: GiftIcon,
  'code-square': CodeSquareIcon,
  'device-desktop': DeviceDesktopIcon,
  graph: GraphIcon,
  'git-pull-request': GitPullRequestIcon,
  beaker: BeakerIcon,
  'mark-github': MarkGithubIcon,
}

function getExploreIcon(octicon: ExplorePage['octicon']): Icon {
  return EXPLORE_ICON_MAP[octicon] ?? SearchIcon
}

function mapExplorePage(page: ExplorePage): QuickSearchSuggestion {
  const idSlug = page.title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
  return {
    id: `explore-${idSlug}`,
    icon: getExploreIcon(page.octicon),
    displayName: page.title,
    href: page.url,
    ariaLabel: `Explore ${page.title}`,
    action: 'jump-to',
    group: 'suggestions',
  }
}

function buildExploreSuggestions(pages: ExplorePage[]): QuickSearchSuggestion[] {
  return pages.map(mapExplorePage)
}

export function filterExplorePages(query: string): QuickSearchSuggestion[] {
  const normalized = query.trim().toLowerCase()
  if (!normalized) return buildExploreSuggestions(ExplorePages).slice(0, MAX_LOGGED_OUT_SUGGESTIONS)

  const filtered = ExplorePages.filter(page => page.title.toLowerCase().includes(normalized))

  return buildExploreSuggestions(filtered).slice(0, MAX_LOGGED_OUT_SUGGESTIONS)
}
